select u.id, u.content_sha256, 'Ao jurado que, sem causa legítima, deixar de comparecer no dia marcado para a sessão ou retirar-se antes de ser dispensado pelo presidente será aplicada multa de 1 a 10 salários mínimos, a critério do juiz, de acordo com a sua condição econômica.', '["Falta sem causa legítima ou saída antes da dispensa.","Multa de 1 a 10 salários mínimos, conforme a condição econômica."]'::jsonb, '["Mesma faixa de multa do art. 436, §2º."]'::jsonb, 'O jurado se retira antes da dispensa e sofre multa.', '["Assertiva que fixa a multa em até 100 salários mínimos para o jurado faltoso erra: é de 1 a 10."]'::jsonb, '[]'::jsonb, '["Art. 436","Art. 443"]'::jsonb, 'under_review', 'claude'
