select u.id, u.content_sha256, 'O jurado, no exercício da função ou a pretexto de exercê-la, será responsável criminalmente nos mesmos termos em que o são os juízes togados.', '["Jurado tem responsabilidade criminal equiparada à dos juízes togados."]'::jsonb, '["Equiparação para fins de responsabilidade penal."]'::jsonb, 'O jurado que recebe vantagem para votar responde como um juiz.', '["Assertiva que isenta o jurado de responsabilidade criminal pelo voto erra."]'::jsonb, '[]'::jsonb, '["Art. 446"]'::jsonb, 'under_review', 'claude'
