select u.id, u.content_sha256, 'Aos suplentes, quando convocados, serão aplicáveis os dispositivos referentes às dispensas, faltas e escusas e à equiparação de responsabilidade penal prevista no art. 445.', '["Suplentes convocados seguem as regras de dispensa, falta e escusa.","Responsabilidade penal equiparada à dos juízes."]'::jsonb, '["Aplica-se quando convocados."]'::jsonb, 'O suplente convocado que falta sem causa legítima também sofre multa.', '["Assertiva que isenta o suplente convocado das regras de falta e escusa erra."]'::jsonb, '[]'::jsonb, '["Art. 445"]'::jsonb, 'under_review', 'claude'
