insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São impedidos de servir no mesmo Conselho: marido e mulher; ascendente e descendente; sogro e genro ou nora; irmãos e cunhados, durante o cunhadio; tio e sobrinho; e padrasto, madrasta ou enteado. O mesmo impedimento ocorre em relação às pessoas que mantenham união estável reconhecida como entidade familiar. Aplica-se aos jurados o disposto sobre os impedimentos, a suspeição e as incompatibilidades dos juízes togados.', '["Impedidos no mesmo Conselho: cônjuges, ascendente e descendente, sogro e genro ou nora, irmãos e cunhados, tio e sobrinho, padrasto, madrasta ou enteado.","União estável equipara-se.","Impedimentos e suspeição dos juízes aplicam-se aos jurados."]'::jsonb, '["Inclui companheiros em união estável."]'::jsonb, 'Marido e mulher não podem compor o mesmo Conselho de Sentença.', '["Assertiva que exclui companheiros em união estável do impedimento erra."]'::jsonb, '[]'::jsonb, '["Art. 449","Art. 252"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-448'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Não poderá servir o jurado que tiver funcionado em julgamento anterior do mesmo processo, independentemente da causa determinante do julgamento posterior; que, no caso de concurso de pessoas, houver integrado o Conselho de Sentença que julgou o outro acusado; ou que tiver manifestado prévia disposição para condenar ou absolver o acusado.', '["I: já funcionou em julgamento anterior do mesmo processo.","II: integrou o Conselho que julgou o corréu.","III: manifestou prévia disposição para condenar ou absolver."]'::jsonb, '["Três hipóteses de incompatibilidade."]'::jsonb, 'Quem julgou o corréu em sessão anterior não integra o Conselho que julgará o outro.', '["Assertiva que permite ao jurado de julgamento anterior do mesmo processo atuar no novo julgamento erra."]'::jsonb, '[]'::jsonb, '["Art. 448"]'::jsonb, 'under_review', 'claude'
