insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Verificando que se encontram na urna as cédulas relativas aos jurados presentes, o juiz presidente sorteará 7 dentre eles para a formação do Conselho de Sentença.', '["Verificação das cédulas dos jurados presentes na urna.","Sorteio de 7 para o Conselho de Sentença."]'::jsonb, '["Sete jurados."]'::jsonb, 'O juiz presidente sorteia 7 jurados presentes para o Conselho.', '["Assertiva que fixa em 5 o número de sorteados para o Conselho erra: são 7."]'::jsonb, '[]'::jsonb, '["Art. 447","Art. 468"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-467'
