insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'À medida que as cédulas forem sendo retiradas da urna, o juiz presidente as lerá, e a defesa e, depois dela, o Ministério Público poderão recusar os jurados sorteados, até 3 cada parte, sem motivar a recusa. O jurado recusado imotivadamente por qualquer das partes será excluído daquela sessão, prosseguindo-se o sorteio com os jurados remanescentes.', '["Recusa imotivada (peremptória): até 3 por parte.","A defesa recusa primeiro, depois o MP.","Jurado recusado é excluído da sessão."]'::jsonb, '["Defesa primeiro, MP depois.","3 recusas por parte."]'::jsonb, 'A defesa recusa três jurados sem dar motivos, e o MP faz o mesmo.', '["Assertiva que permite 5 recusas imotivadas por parte erra: são 3."]'::jsonb, '[{"termo":"Recusa peremptória","significado":"Recusa de jurado sem necessidade de motivar."}]'::jsonb, '["Art. 467","Art. 469"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-468'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se forem 2 ou mais os acusados, as recusas poderão ser feitas por um só defensor. A separação dos julgamentos somente ocorrerá se, em razão das recusas, não for obtido o número mínimo de 7 jurados para compor o Conselho de Sentença. Determinada a separação, será julgado em primeiro lugar o acusado a quem foi atribuída a autoria do fato ou, em caso de coautoria, aplicar-se-á o critério de preferência do art. 429.', '["Vários acusados: recusas por um só defensor.","Separação dos julgamentos só se faltarem 7 jurados por causa das recusas.","Primeiro julga-se o autor; na coautoria, o critério do art. 429."]'::jsonb, '["Separação apenas se faltar o número mínimo de 7."]'::jsonb, 'As recusas esgotam os jurados, e os julgamentos são separados.', '["Assertiva que separa os julgamentos sempre que há mais de um acusado erra."]'::jsonb, '[]'::jsonb, '["Art. 429","Art. 468"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-469'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Desacolhida a arguição de impedimento, de suspeição ou de incompatibilidade contra o juiz presidente do Tribunal do Júri, órgão do Ministério Público, jurado ou qualquer funcionário, o julgamento não será suspenso, devendo, entretanto, constar da ata o seu fundamento e a decisão.', '["Arguição desacolhida não suspende o julgamento.","Fundamento e decisão constam da ata."]'::jsonb, '["A ata registra o fundamento (para eventual recurso)."]'::jsonb, 'A defesa argui a suspeição de um jurado; rejeitada, o julgamento prossegue e a ata registra.', '["Assertiva que suspende o julgamento diante de arguição desacolhida erra."]'::jsonb, '[]'::jsonb, '["Art. 471"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-470'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se, em consequência do impedimento, suspeição, incompatibilidade, dispensa ou recusa, não houver número para a formação do Conselho, o julgamento será adiado para o primeiro dia desimpedido, após sorteados os suplentes, com observância do art. 464.', '["Sem número para formar o Conselho: adiamento para o primeiro dia desimpedido.","Sorteio de suplentes, segundo o art. 464."]'::jsonb, '["Adiamento e sorteio de suplentes."]'::jsonb, 'Recusas e impedimentos esgotam os jurados: adia-se e sorteiam-se suplentes.', '["Assertiva que forma o Conselho com menos de 7 jurados erra."]'::jsonb, '[]'::jsonb, '["Art. 464"]'::jsonb, 'under_review', 'claude'
