insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Formado o Conselho de Sentença, o presidente, levantando-se, e, com ele, todos os presentes, fará aos jurados a exortação: ''Em nome da lei, concito-vos a examinar esta causa com imparcialidade e a proferir a vossa decisão de acordo com a vossa consciência e os ditames da justiça.'' Os jurados, nominalmente chamados, responderão: ''Assim o prometo.'' O jurado, em seguida, receberá cópias da pronúncia ou das decisões posteriores que julgaram admissível a acusação e do relatório do processo.', '["Compromisso solene dos jurados.","Todos de pé; resposta ''Assim o prometo''.","Entrega aos jurados de cópias da pronúncia e do relatório."]'::jsonb, '["Jurados recebem a pronúncia e o relatório."]'::jsonb, 'Os jurados prestam o compromisso e recebem cópia da pronúncia.', '["Assertiva que dispensa a entrega de cópia da pronúncia aos jurados erra."]'::jsonb, '[]'::jsonb, '["Art. 473"]'::jsonb, 'under_review', 'claude'
