insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Prestado o compromisso pelos jurados, será iniciada a instrução plenária, quando o juiz presidente, o Ministério Público, o assistente, o querelante e o defensor do acusado tomarão, sucessiva e diretamente, as declarações do ofendido, se possível, e inquirirão as testemunhas arroladas pela acusação. Para a inquirição das testemunhas da defesa, o defensor formulará as perguntas antes do Ministério Público e do assistente. Os jurados poderão formular perguntas ao ofendido e às testemunhas, por intermédio do juiz presidente. As partes e os jurados poderão requerer acareações, reconhecimento de pessoas e coisas e esclarecimento dos peritos, bem como a leitura de peças que se refiram, exclusivamente, às provas colhidas por carta precatória e às provas cautelares, antecipadas ou não repetíveis.', '["Instrução plenária: juiz, MP, assistente, querelante e defensor perguntam sucessiva e diretamente.","Testemunhas da defesa: o defensor pergunta primeiro.","Jurados perguntam por intermédio do juiz presidente.","Acareações, reconhecimentos, esclarecimentos de peritos e leitura restrita de peças."]'::jsonb, '["Jurados perguntam POR INTERMÉDIO do juiz.","Testemunha de defesa: o defensor inicia."]'::jsonb, 'Um jurado submete sua pergunta ao juiz presidente, que a formula à testemunha.', '["Assertiva que permite ao jurado perguntar diretamente à testemunha erra."]'::jsonb, '[]'::jsonb, '["Art. 474"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-473'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Em seguida, o acusado será interrogado, se estiver presente, na forma estabelecida no Capítulo III do Título VII do Livro I do Código, com as alterações introduzidas nesta Seção. O Ministério Público, o assistente, o querelante e o defensor, nessa ordem, poderão formular, diretamente, perguntas ao acusado. Os jurados formularão perguntas por intermédio do juiz presidente. Não se permitirá o uso de algemas no acusado durante o período em que permanecer no plenário do júri, salvo se absolutamente necessário à ordem dos trabalhos, à segurança das testemunhas ou à garantia da integridade física dos presentes.', '["Acusado interrogado no plenário, se presente.","Perguntas diretas: MP, assistente, querelante e defensor, nessa ordem.","Jurados por intermédio do juiz presidente.","Sem algemas no plenário, salvo absoluta necessidade."]'::jsonb, '["Algemas: exceção por absoluta necessidade (e Súmula Vinculante 11)."]'::jsonb, 'O acusado é interrogado sem algemas no plenário.', '["Assertiva que permite o uso rotineiro de algemas no plenário erra."]'::jsonb, '[]'::jsonb, '["Art. 473"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-474'
