insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Durante a instrução em plenário, todas as partes e demais sujeitos processuais presentes no ato deverão respeitar a dignidade da vítima, sob pena de responsabilização civil, penal e administrativa, cabendo ao juiz presidente garantir o cumprimento do disposto, sendo vedadas a manifestação sobre circunstâncias ou elementos alheios aos fatos objeto de apuração nos autos e a utilização de linguagem, informações ou material que ofendam a dignidade da vítima ou de testemunhas.', '["Respeito à dignidade da vítima no plenário.","Responsabilidade civil, penal e administrativa.","Vedadas manifestações alheias aos fatos e linguagem ofensiva."]'::jsonb, '["Incluído pela Lei nº 14.245, de 2021."]'::jsonb, 'O juiz presidente impede o uso de material ofensivo à vítima no plenário.', '["Assertiva que restringe o art. 474-A aos crimes sexuais erra."]'::jsonb, '[]'::jsonb, '["Art. 400-A"]'::jsonb, 'under_review', 'claude'
