insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O tempo destinado à acusação e à defesa será de uma hora e meia para cada, e de uma hora para a réplica e outro tanto para a tréplica. Havendo mais de um acusador ou mais de um defensor, combinarão entre si a distribuição do tempo, que, na falta de acordo, será dividido pelo juiz presidente, de forma a não exceder o determinado. Havendo mais de 1 acusado, o tempo para a acusação e a defesa será acrescido de 1 hora e elevado ao dobro o da réplica e da tréplica.', '["Acusação e defesa: uma hora e meia cada.","Réplica e tréplica: uma hora cada.","Vários acusadores ou defensores dividem o tempo.","Mais de 1 acusado: acréscimo de 1 hora e réplica e tréplica em dobro."]'::jsonb, '["Tempos: 1h30 (debate) e 1h (réplica/tréplica).","Mais de um acusado: +1 hora e dobro da réplica e da tréplica."]'::jsonb, 'Em plenário com um acusado, cada parte tem uma hora e meia para o debate.', '["Assertiva que fixa em duas horas o tempo de debate com um só acusado erra: é uma hora e meia."]'::jsonb, '[]'::jsonb, '["Art. 476"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-477'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Durante os debates as partes não poderão, sob pena de nulidade, fazer referências à decisão de pronúncia, às decisões posteriores que julgaram admissível a acusação ou à determinação do uso de algemas como argumento de autoridade que beneficiem ou prejudiquem o acusado; nem ao silêncio do acusado ou à ausência de interrogatório por falta de requerimento, em seu prejuízo.', '["Proibido invocar a pronúncia como argumento de autoridade.","Proibido usar o uso de algemas como argumento de autoridade.","Proibido usar o silêncio do acusado em seu prejuízo.","Sob pena de nulidade."]'::jsonb, '["Nulidade se as vedações forem descumpridas."]'::jsonb, 'O promotor diz aos jurados que o juiz já entendeu pela culpa ao pronunciar: nulidade.', '["Assertiva que permite ao MP citar o silêncio do acusado como indício de culpa erra."]'::jsonb, '[]'::jsonb, '["Art. 186"]'::jsonb, 'under_review', 'claude'
