insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Durante o julgamento não será permitida a leitura de documento ou a exibição de objeto que não tiver sido juntado aos autos com a antecedência mínima de 3 dias úteis, dando-se ciência à outra parte. Compreende-se na proibição a leitura de jornais ou qualquer outro escrito, bem como a exibição de vídeos, gravações, fotografias, laudos, quadros, croqui ou qualquer outro meio assemelhado, cujo conteúdo versar sobre a matéria de fato submetida à apreciação e julgamento dos jurados.', '["Documento ou objeto deve ser juntado aos autos com antecedência mínima de 3 dias úteis, com ciência à outra parte.","A vedação abrange jornais, vídeos, gravações, fotografias, laudos, quadros e croqui sobre a matéria de fato."]'::jsonb, '["Antecedência de 3 dias ÚTEIS."]'::jsonb, 'A defesa não pode exibir no plenário um vídeo juntado no dia do julgamento.', '["Assertiva que fixa em 24 horas a antecedência para exibir documentos no plenário erra: são 3 dias úteis."]'::jsonb, '[]'::jsonb, '["Art. 231"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-479'
