insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se a verificação de qualquer fato, reconhecida como essencial para o julgamento da causa, não puder ser realizada imediatamente, o juiz presidente dissolverá o Conselho, ordenando a realização das diligências entendidas necessárias. Se a diligência consistir na produção de prova pericial, o juiz presidente, desde logo, nomeará perito e formulará quesitos, facultando às partes também formulá-los e indicar assistentes técnicos, no prazo de 5 dias.', '["Fato essencial não verificável de imediato: dissolução do Conselho e diligências.","Prova pericial: perito nomeado e quesitos do juiz.","Partes formulam quesitos e indicam assistentes técnicos em 5 dias."]'::jsonb, '["Dissolução do Conselho de Sentença."]'::jsonb, 'Uma perícia essencial é necessária; o Conselho é dissolvido e o perito, nomeado.', '["Assertiva que mantém o Conselho de Sentença enquanto aguarda a diligência essencial erra."]'::jsonb, '[]'::jsonb, '["Art. 480"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-481'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Conselho de Sentença será questionado sobre matéria de fato e se o acusado deve ser absolvido. Os quesitos serão redigidos em proposições afirmativas, simples e distintas, de modo que cada um possa ser respondido com suficiente clareza e necessária precisão, levando o presidente em conta os termos da pronúncia, do interrogatório e das alegações das partes.', '["Os jurados respondem sobre matéria de FATO e sobre a absolvição.","Quesitos: afirmativos, simples e distintos.","Redação com base na pronúncia, no interrogatório e nas alegações das partes."]'::jsonb, '["Os jurados não decidem questões de direito."]'::jsonb, 'O quesito é formulado de forma afirmativa e simples, para ser respondido com ''sim'' ou ''não''.', '["Assertiva que permite quesitos complexos e negativos erra: devem ser afirmativos, simples e distintos."]'::jsonb, '[]'::jsonb, '["Art. 483"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-482'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os quesitos serão formulados na seguinte ordem: materialidade do fato; autoria ou participação; se o acusado deve ser absolvido; se existe causa de diminuição de pena alegada pela defesa; e se existe circunstância qualificadora ou causa de aumento de pena reconhecidas na pronúncia. A resposta negativa, de mais de 3 jurados, a qualquer dos quesitos dos incisos I e II encerra a votação e implica a absolvição. Respondidos afirmativamente por mais de 3 jurados os quesitos I e II, será formulado o quesito: ''O jurado absolve o acusado?''. Decidindo os jurados pela condenação, o julgamento prossegue, com quesitos sobre causa de diminuição de pena e circunstância qualificadora ou causa de aumento. O dispositivo remete à ADPF 779.', '["Ordem: I materialidade; II autoria ou participação; III absolvição; IV causa de diminuição; V qualificadora ou causa de aumento.","Negativa de mais de 3 jurados em I ou II: absolvição.","Afirmativa em I e II: quesito genérico ''O jurado absolve o acusado?''.","Condenação: quesitos sobre diminuição e qualificadora/aumento."]'::jsonb, '["Mais de 3 jurados = maioria (de 7).","O quesito da absolvição (genérico) é obrigatório."]'::jsonb, 'Quatro jurados negam a autoria: o acusado é absolvido e a votação se encerra.', '["Assertiva que coloca o quesito de qualificadora antes da autoria erra: autoria vem antes."]'::jsonb, '[{"termo":"Quesito genérico","significado":"''O jurado absolve o acusado?'', terceiro quesito da série."}]'::jsonb, '["Art. 482","Art. 489"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-483'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O presidente lerá os quesitos e indagará das partes se têm requerimento ou reclamação a fazer, devendo qualquer deles, bem como a decisão, constar da ata. Ainda em plenário, o juiz presidente explicará aos jurados o significado de cada quesito.', '["Leitura dos quesitos e oportunidade de requerimento ou reclamação.","Requerimentos e decisão constam da ata.","Explicação do significado de cada quesito aos jurados."]'::jsonb, '["Reclamação não registrada em ata gera preclusão."]'::jsonb, 'A defesa reclama de um quesito, e a ata registra a reclamação e a decisão.', '["Assertiva que dispensa o registro em ata das reclamações sobre os quesitos erra."]'::jsonb, '[]'::jsonb, '["Art. 483"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-484'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Não havendo dúvida a ser esclarecida, o juiz presidente, os jurados, o Ministério Público, o assistente, o querelante, o defensor do acusado, o escrivão e o oficial de justiça dirigir-se-ão à sala especial a fim de ser procedida a votação. Na falta de sala especial, o juiz presidente determinará que o público se retire, permanecendo somente as pessoas mencionadas. O juiz presidente advertirá as partes de que não será permitida qualquer intervenção que possa perturbar a livre manifestação do Conselho e fará retirar da sala quem se portar inconvenientemente.', '["Votação em sala especial, com presentes limitados.","Sem sala especial: público se retira.","Proibida intervenção que perturbe a livre manifestação do Conselho."]'::jsonb, '["Sigilo da votação, mas com a presença de partes e escrivão."]'::jsonb, 'Sem sala especial, o público é retirado e a votação ocorre no plenário.', '["Assertiva que permite a presença do público na votação, na falta de sala especial, erra."]'::jsonb, '[{"termo":"Sala especial","significado":"Local da votação dos quesitos, com acesso restrito."}]'::jsonb, '["Art. 486"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-485'
