insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Antes de proceder-se à votação de cada quesito, o juiz presidente mandará distribuir aos jurados pequenas cédulas, feitas de papel opaco e facilmente dobráveis, contendo 7 delas a palavra sim, 7 a palavra não.', '["Cédulas de papel opaco e facilmente dobráveis.","7 com ''sim'' e 7 com ''não'' para cada jurado."]'::jsonb, '["7 cédulas ''sim'' e 7 ''não''."]'::jsonb, 'Cada jurado recebe 7 cédulas ''sim'' e 7 ''não'' antes de cada quesito.', '["Assertiva que fixa em 3 cédulas de cada tipo a distribuição erra: são 7 de cada."]'::jsonb, '[]'::jsonb, '["Art. 487"]'::jsonb, 'under_review', 'claude'
