select u.id, u.content_sha256, 'As decisões do Tribunal do Júri serão tomadas por maioria de votos.', '["Decisões do Júri por maioria de votos."]'::jsonb, '["Voto secreto e soberania dos veredictos (Constituição, art. 5º, XXXVIII)."]'::jsonb, 'Quatro votos ''sim'' decidem o quesito.', '["Assertiva que exige unanimidade para as decisões do Júri erra: basta maioria."]'::jsonb, '[]'::jsonb, '["Art. 483"]'::jsonb, 'under_review', 'claude'
