insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A ata descreverá fielmente todas as ocorrências, mencionando obrigatoriamente, entre outros itens: a data e a hora da instalação dos trabalhos; o magistrado que presidiu a sessão e os jurados presentes; os jurados que deixaram de comparecer, com escusa ou sem ela, e as sanções aplicadas; o ofício ou requerimento de isenção ou dispensa; o sorteio dos suplentes; o adiamento da sessão, com o motivo; a abertura da sessão e a presença do MP, do querelante, do assistente e do defensor; o pregão e a sanção imposta, no caso de não comparecimento; as testemunhas dispensadas de depor; e o recolhimento das testemunhas a lugar onde umas não ouvissem as outras.', '["Ata fiel, com elementos obrigatórios.","Instalação, magistrado, jurados presentes e faltosos.","Isenções, dispensas, suplentes e adiamentos.","Presença das partes, pregão, testemunhas dispensadas e incomunicabilidade."]'::jsonb, '["Rol extenso de itens obrigatórios."]'::jsonb, 'A ata registra o horário de instalação e os jurados presentes.', '["Assertiva que dispensa a menção dos jurados faltosos na ata erra."]'::jsonb, '[]'::jsonb, '["Art. 494"]'::jsonb, 'under_review', 'claude'
