insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São atribuições do juiz presidente do Tribunal do Júri, além de outras referidas no Código: regular a polícia das sessões e prender os desobedientes; requisitar o auxílio da força pública, que ficará sob sua exclusiva autoridade; dirigir os debates, intervindo em caso de abuso, excesso de linguagem ou mediante requerimento de uma das partes; resolver as questões incidentes que não dependam de pronunciamento do júri; nomear defensor ao acusado, quando considerá-lo indefeso, podendo dissolver o Conselho e designar novo dia; mandar retirar da sala o acusado que dificultar a realização do julgamento, o qual prosseguirá sem a sua presença; e suspender a sessão pelo tempo indispensável à realização das diligências, mantida a incomunicabilidade dos jurados, entre outras atribuições.', '["Polícia das sessões e prisão dos desobedientes.","Força pública sob sua exclusiva autoridade.","Direção dos debates e coibição de excessos.","Questões incidentes que não dependam do júri.","Nomeação de defensor se o acusado estiver indefeso, com possível dissolução do Conselho.","Retirada do acusado que dificulta o julgamento.","Suspensão da sessão para diligências, com incomunicabilidade dos jurados."]'::jsonb, '["Defesa deficiente: o juiz nomeia defensor e pode dissolver o Conselho."]'::jsonb, 'O juiz presidente considera o acusado indefeso, nomeia novo defensor e dissolve o Conselho.', '["Assertiva que impede o juiz presidente de dissolver o Conselho por defesa deficiente erra."]'::jsonb, '[]'::jsonb, '["Art. 481"]'::jsonb, 'under_review', 'claude'
