insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nos crimes afiançáveis, estando a denúncia ou queixa em devida forma, o juiz mandará autuá-la e ordenará a notificação do acusado, para responder por escrito, dentro do prazo de quinze dias. Se não for conhecida a residência do acusado, ou este se achar fora da jurisdição do juiz, ser-lhe-á nomeado defensor, a quem caberá apresentar a resposta preliminar.', '["Crimes afiançáveis de funcionários: notificação para resposta preliminar em quinze dias.","Sem residência conhecida ou fora da jurisdição: defensor nomeado."]'::jsonb, '["A Súmula 330 do STJ dispensa a defesa preliminar se a ação é instruída por inquérito policial."]'::jsonb, 'O servidor é notificado para responder por escrito em quinze dias.', '["Assertiva que fixa em 10 dias a resposta preliminar do art. 514 erra: são quinze dias."]'::jsonb, '[]'::jsonb, '["Art. 513","Art. 516"]'::jsonb, 'under_review', 'claude'
